INSERT INTO `knowledge_project_note` VALUES (1,'e.g.github_key','<p>e.g.github_key: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</p>\n<p>&lt;style&gt;*{color:red}&lt;/style&gt;</p>','2025-10-26 08:02:02.129839','2026-01-25 11:00:14.608712',0,'e5e21a131ea04f939de6053cc046eaaf',2,2,0,'[]',NULL,0,0,NULL,1),(2,'智谱api','<ul class=\"info-list\">\n<li class=\"list-items\">\n<div class=\"items-title\">key0a5c4fa41d6248e58ce42f2f2b2b23bd.xj0soWJr8ZFoBfid</div>\n</li>\n</ul>','2025-11-16 12:48:43.376913','2026-01-21 14:57:59.133543',0,'d46a2a589ca9492e853f6cee838dae0d',2,2,0,'[]',3,1,0,'2026-01-25 10:46:54.718576',0),(3,'123','<p>123</p>','2025-12-04 15:19:46.296418','2025-12-04 15:19:59.750227',0,'1a36d3bc2f784aa0888050f55843858f',23,23,0,'[]',NULL,0,0,NULL,0),(4,'无标题笔记','<p>dada</p>','2025-12-14 15:23:51.525558','2025-12-14 15:34:03.953770',0,'c9b223b1200f450885035d0f2e298a64',39,39,0,'[]',NULL,0,0,NULL,0),(5,'无标题笔记','','2025-12-14 15:35:47.708213','2025-12-14 15:35:49.320030',0,'8a81a6684fd54feeb6b6714c94cc0db3',39,39,0,'[]',NULL,0,0,NULL,0),(7,'Turnstile 小组件','<div class=\"c_du c_dv c_e\"><header class=\"\">\n<p class=\"c_dw c_dl c_dx c_dy c_dz\">Turnstile</p>\n<div class=\"c_d c_o\">\n<h1 class=\"c_dl c_ea c_eb c_dy c_f c_ec\" id=\"\">添加小组件</h1>\n</div>\n<div class=\"__react_component_tooltip place-right type-dark\"> </div>\n</header></div>\n<div class=\"c_hx\">\n<div class=\"\">\n<div class=\"c_aq c_cg c_ch c_ace c_q c_gf c_gg c_fc c_fd c_dq c_acf c_acg c_ach\">已成功创建 Turnstile 小组件！</div>\n</div>\n<div class=\"c_hx c_vo\">\n<p class=\"\">您现在可以配置您的网站来使用 Turnstile：</p>\n<p class=\"\"> </p>\n<div class=\"c_ea\"><a class=\"c_gi c_o\" href=\"https://developers.cloudflare.com/turnstile/get-started/client-side-rendering/\" rel=\"noopener noreferrer\" target=\"_blank\">客户端集成代码</a></div>\n<div class=\"c_hx\"><a class=\"c_gi c_o\" href=\"https://developers.cloudflare.com/turnstile/get-started/server-side-validation/\" rel=\"noopener noreferrer\" target=\"_blank\">服务器端集成代码</a></div>\n<p> </p>\n<div class=\"c_dq\">\n<div class=\"c_bv\">\n<div class=\"c_d c_e\">站点密钥0x4AAAAAACHCR25nYE5MiobN</div>\n<div class=\"c_bv\">\n<div class=\"\">\n<div class=\"c_af c_to c_acl\"> </div>\n</div>\n</div>\n</div>\n</div>\n<div class=\"c_dq\">\n<div class=\"c_bv\">\n<div class=\"c_d c_e\">密钥0x4AAAAAACHCRxGebdu5PxdEm73CaFRRWTY</div>\n<div class=\"c_bv\">\n<div class=\"\">\n<div class=\"c_af c_to c_acl\"> </div>\n</div>\n单击以复制</div>\n</div>\n</div>\n<div class=\"c_aq c_cg c_ch c_ace c_q c_gf c_gg c_fc c_fd c_dq c_acn c_aco c_acp\">注意：您以后可以再次查看您的密钥。</div>\n</div>\n</div>','2025-12-16 16:43:43.736788','2026-01-25 10:47:04.288570',0,'c1152ff9fc754d9c994dc2ed7beb9e64',2,2,38,'[{\"id\": \"\", \"text\": \"添加小组件\", \"level\": 1}]',NULL,0,1,NULL,1),(13,'CLIProxyAPI','<h1 id=\"cliproxyapi-quick-start\">🚀 CLIProxyAPI 搭建笔记 (Quick Start)</h1>\n<h2 id=\"\"><strong>项目简介</strong></h2>\n<p> CLIProxyAPI 是一个开源网关（Go语言编写），它将各类 AI 模型的命令行接口（CLI）——如 Gemini CLI、Claude Code、ChatGPT Codex——封装为标准的 OpenAI/Claude 兼容 API。</p>\n<ul>\n<li>\n<p><strong>核心用途</strong>：让 Cline、Cursor、Open WebUI 等客户端能够调用 CLI 渠道的“免费”或“配额独立”的模型资源（如 Gemini 2.5 Pro, Claude 3.7 Sonnet via CLI）。</p>\n</li>\n<li>\n<p><strong>GitHub</strong>：<code>router-for-me/CLIProxyAPI</code></p>\n</li>\n</ul>\n<hr/>\n<h2 id=\"-2\">🛠️ 环境准备</h2>\n<ul>\n<li>\n<p><strong>OS</strong>: Windows x64 (建议使用 Docker Desktop 或 WSL2)</p>\n</li>\n<li>\n<p><strong>依赖</strong>: Docker (推荐) 或 Go 环境</p>\n</li>\n<li>\n<p><strong>网络</strong>: 需要能够访问 Google/Anthropic 的网络环境（建议配置 Clash 等系统代理）</p>\n</li>\n</ul>\n<hr/>\n<h2 id=\"-3\">📦 部署方案 ：</h2>\n<p>1.Docker Compose (推荐)</p>\n<p>这是最干净的部署方式，方便管理配置和日志。</p>\n<div class=\"code-block ng-tns-c2283161342-148 ng-animate-disabled ng-trigger ng-trigger-codeBlockRevealAnimation\">\n<div class=\"code-block-decoration header-formatted gds-title-s ng-tns-c2283161342-148 ng-star-inserted\">macOS\n<div class=\"language-bash\">\n<pre class=\"shiki shiki-themes github-light github-dark\"><code><span class=\"line\">brew install cliproxyapi</span>\n<span class=\"line\"> brew services start cliproxyapi</span></code></pre>\n</div>\nLinux\n<div class=\"language-bash\">\n<pre class=\"shiki shiki-themes github-light github-dark\"><code><span class=\"line\">curl -fsSL https://raw.githubusercontent.com/brokechubb/cliproxyapi-installer/refs/heads/master/cliproxyapi-installer | bash</span></code></pre>\n</div>\n<p>进入<code class=\"code-container formatted ng-tns-c2283161342-148\">CLIProxyAPI</code>目录</p>\n<div class=\"buttons ng-tns-c2283161342-148 ng-star-inserted\"> </div>\n</div>\n<div class=\"formatted-code-block-internal-container ng-tns-c2283161342-148\">\n<div class=\"animated-opacity ng-tns-c2283161342-148\">\n<pre class=\"ng-tns-c2283161342-148\"><code class=\"code-container formatted ng-tns-c2283161342-148\">CLIProxyAPI/\n├── docker-compose.yml\n├── config.yaml\n└── auths/           &lt;-- 用于持久化保存登录凭证\n</code></pre>\n</div>\n</div>\n</div>\n<h3 id=\"2-docker-composeyml\">2. 编写 <code>docker-compose.yml</code></h3>\n<div class=\"code-block ng-tns-c2283161342-149 ng-animate-disabled ng-trigger ng-trigger-codeBlockRevealAnimation\">\n<div class=\"formatted-code-block-internal-container ng-tns-c2283161342-149\">\n<div class=\"animated-opacity ng-tns-c2283161342-149\">\n<pre class=\"ng-tns-c2283161342-149\"><code class=\"code-container formatted ng-tns-c2283161342-149\"><span class=\"hljs-attr\">services:</span>\n  <span class=\"hljs-attr\">cli-proxy:</span>\n    <span class=\"hljs-attr\">image:</span> <span class=\"hljs-string\">ghcr.io/router-for-me/cliproxyapi:latest</span> <span class=\"hljs-comment\">#</span>\n    <span class=\"hljs-attr\">container_name:</span> <span class=\"hljs-string\">cli-proxy-api</span>\n    <span class=\"hljs-attr\">restart:</span> <span class=\"hljs-string\">always</span>\n    <span class=\"hljs-attr\">ports:</span>\n      <span class=\"hljs-bullet\">-</span> <span class=\"hljs-string\">\"8080:8080\"</span> <span class=\"hljs-comment\"># API 服务端口</span>\n      <span class=\"hljs-bullet\">-</span> <span class=\"hljs-string\">\"9090:9090\"</span> <span class=\"hljs-comment\"># Web 管理面板端口 (可选)</span>\n    <span class=\"hljs-attr\">volumes:</span>\n      <span class=\"hljs-bullet\">-</span> <span class=\"hljs-string\">./config.yaml:/app/config.yaml</span>\n      <span class=\"hljs-bullet\">-</span> <span class=\"hljs-string\">./auths:/app/auths</span> <span class=\"hljs-comment\"># 映射认证目录，重启后免登录</span>\n    <span class=\"hljs-attr\">environment:</span>\n      <span class=\"hljs-bullet\">-</span> <span class=\"hljs-string\">TZ=Asia/Shanghai</span>\n    <span class=\"hljs-comment\"># 如果你在 Windows 上运行 Docker，想让容器走宿主机的代理软件</span>\n    <span class=\"hljs-comment\"># extra_hosts:</span>\n    <span class=\"hljs-comment\">#   - \"host.docker.internal:host-gateway\" </span>\n</code></pre>\n</div>\n</div>\n</div>\n<p>3. 配置 <code>config.yaml</code></p>\n<p>这是核心配置文件，用于定义 API Key 和路由规则。</p>\n<div class=\"code-block ng-tns-c2283161342-150 ng-animate-disabled ng-trigger ng-trigger-codeBlockRevealAnimation\">\n<div class=\"formatted-code-block-internal-container ng-tns-c2283161342-150\">\n<pre class=\"animated-opacity ng-tns-c2283161342-150\"># 服务器绑定的主机/接口。默认为空 (\"\")，表示绑定所有接口 (IPv4 + IPv6)。<br/># 使用 \"127.0.0.1\" 或 \"localhost\" 可限制为仅允许本机访问。<br/>host: \"\"<br/># 服务器端口<br/>port: 8317<br/># HTTPS 的 TLS 设置。启用后，服务器将使用提供的证书和密钥进行监听。<br/>tls:<br/>  enable: False<br/>  cert: \"\"<br/>  key: \"\"<br/># 管理 API 设置<br/>remote-management:<br/>  # 是否允许远程（非本机）管理访问。<br/>  # 如果为 false，则只有本机 (localhost) 可以访问管理端点（仍需要密钥）。<br/>  allow-remote: true<br/>  # 管理密钥。如果此处提供明文值，启动时会被哈希处理。<br/>  # 所有管理请求（即便是来自 localhost）都需要此密钥。<br/>  # 留空则完全禁用管理 API（所有 /v0/management 路由返回 404）。<br/>  secret-key: \"******\"<br/>  # 设置为 true 时，禁用内置的管理控制台资源下载和 HTTP 路由。<br/>  disable-control-panel: false<br/>  # 管理控制台的 GitHub 仓库。接受仓库 URL 或 Releases API URL。<br/>  panel-github-repository: \"https://github.com/router-for-me/Cli-Proxy-API-Management-Center\"<br/># 认证信息存储目录（支持用 ~ 代表用户主目录）<br/>auth-dir: \"~/.cli-proxy-api\"<br/># 用于客户端认证的 API 密钥 (Bearer Token)<br/>api-keys:<br/>  - \"sk-ftiRC5M0nDSsM6LMDelpyHWL5x9ILsy3c1Nwlq1xJdd64\"<br/>  - \"sk-LjCI3oAd7DKeXin6FvmiDuzZ9pL5MTLGcbIapwgBUQhsl\"<br/>  - \"your-api-key-3\"<br/># 启用调试日志<br/>debug: false<br/># 当为 true 时，禁用高开销的 HTTP 中间件特性，以在高并发下减少每个请求的内存占用。<br/>commercial-mode: false<br/># 当为 true 时，将应用程序日志写入轮转文件，而不是输出到标准输出 (stdout)。<br/>logging-to-file: false<br/># logs 目录下日志文件的最大总大小 (MB)。超出时，将删除最旧的日志文件，直到限制范围内。<br/># 设置为 0 表示禁用此限制。<br/>logs-max-total-size-mb: 0<br/># 当为 false 时，禁用内存中的使用情况统计聚合功能。<br/>usage-statistics-enabled: false<br/># 代理 URL。支持 socks5/http/https 协议。示例: socks5://user:pass@192.168.1.1:1080/<br/>proxy-url: \"\"<br/># 当为 true 时，无前缀的模型请求仅使用无前缀的凭证（除非 前缀 == 模型名）。<br/>force-model-prefix: false<br/># 请求重试次数。如果 HTTP 响应代码为 403, 408, 500, 502, 503 或 504，将进行重试。<br/>request-retry: 3<br/># 触发重试前，已进入冷却状态的凭证的最大等待时间（秒）。<br/>max-retry-interval: 30<br/># 配额耗尽时的行为<br/>quota-exceeded:<br/>  switch-project: true       # 当配额耗尽时，是否自动切换到另一个项目/账号<br/>  switch-preview-model: true # 当配额耗尽时，是否自动降级/切换到预览版模型<br/># 当多个凭证匹配时的路由策略。<br/>routing:<br/>  strategy: \"round-robin\" # round-robin (默认，轮询), fill-first (优先填满第一个)<br/># 当为 true 时，对 WebSocket API (/v1/ws) 启用鉴权。<br/>ws-auth: false<br/># 流式传输行为 (SSE 保活 + 安全引导重试)。<br/># streaming:<br/>#   keepalive-seconds: 15   # 默认: 0 (禁用)。&lt;= 0 表示禁用保活。<br/>#   bootstrap-retries: 1    # 默认: 0 (禁用)。在发送第一个字节之前的重试次数。<br/># Gemini API 密钥配置 (Google AI Studio / Vertex)<br/># gemini-api-key:<br/>#   - api-key: \"AIzaSy...01\"<br/>#     prefix: \"test\" # 可选：要求调用格式如 \"test/gemini-3-pro-preview\" 才能匹配此凭证<br/>#     base-url: \"https://generativelanguage.googleapis.com\"<br/>#     headers:<br/>#       X-Custom-Header: \"custom-value\"<br/>#     proxy-url: \"socks5://proxy.example.com:1080\"<br/>#     models:<br/>#       - name: \"gemini-2.5-flash\" # 上游模型名称<br/>#         alias: \"gemini-flash\"    # 映射到上游模型的客户端别名<br/>#     excluded-models:<br/>#       - \"gemini-2.5-pro\"     # 从此提供商排除特定模型（精确匹配）<br/>#       - \"gemini-2.5-*\"       # 通配符匹配前缀 (例如 gemini-2.5-flash, gemini-2.5-pro)<br/>#       - \"*-preview\"          # 通配符匹配后缀 (例如 gemini-3-pro-preview)<br/>#       - \"*flash*\"            # 通配符匹配子串 (例如 gemini-2.5-flash-lite)<br/>#   - api-key: \"AIzaSy...02\"<br/># Codex API 密钥配置 (OpenAI / ChatGPT)<br/># codex-api-key:<br/>#   - api-key: \"sk-atSM...\"<br/>#     prefix: \"test\" # 可选：要求调用格式如 \"test/gpt-5-codex\" 才能匹配此凭证<br/>#     base-url: \"https://www.example.com\" # 使用自定义 Codex API 端点<br/>#     headers:<br/>#       X-Custom-Header: \"custom-value\"<br/>#     proxy-url: \"socks5://proxy.example.com:1080\" # 可选：针对此 Key 的代理覆盖<br/>#     models:<br/>#       - name: \"gpt-5-codex\"   # 上游模型名称<br/>#         alias: \"codex-latest\" # 客户端别名<br/>#     excluded-models:<br/>#       - \"gpt-5.1\"         # 排除特定模型（精确匹配）<br/>#       - \"gpt-5-*\"         # 通配符前缀<br/>#       - \"*-mini\"          # 通配符后缀<br/>#       - \"*codex*\"         # 通配符子串<br/># Claude API 密钥配置 (Anthropic)<br/># claude-api-key:<br/>#   - api-key: \"sk-atSM...\" # 使用官方 Claude API Key，无需设置 base-url<br/>#   - api-key: \"sk-atSM...\"<br/>#     prefix: \"test\" # 可选：要求调用格式如 \"test/claude-sonnet-latest\" 匹配此凭证<br/>#     base-url: \"https://www.example.com\" # 使用自定义 Claude API 端点<br/>#     headers:<br/>#       X-Custom-Header: \"custom-value\"<br/>#     proxy-url: \"socks5://proxy.example.com:1080\" # 可选：代理覆盖<br/>#     models:<br/>#       - name: \"claude-3-5-sonnet-20241022\" # 上游模型名称<br/>#         alias: \"claude-sonnet-latest\"      # 客户端别名<br/>#     excluded-models:<br/>#       - \"claude-opus-4-5-20251101\" # 排除特定模型<br/>#       - \"claude-3-*\"               # 通配符前缀<br/>#       - \"*-thinking\"               # 通配符后缀<br/>#       - \"*haiku*\"                  # 通配符子串<br/># OpenAI 兼容性提供商配置<br/># openai-compatibility:<br/>#   - name: \"openrouter\" # 提供商名称；将用于 User Agent 和其他地方。<br/>#     prefix: \"test\" # 可选：要求调用格式如 \"test/kimi-k2\" 才能匹配此提供商的凭证<br/>#     base-url: \"https://openrouter.ai/api/v1\" # 提供商的基础 URL。<br/>#     headers:<br/>#       X-Custom-Header: \"custom-value\"<br/>#     api-key-entries:<br/>#       - api-key: \"sk-or-v1-...b780\"<br/>#         proxy-url: \"socks5://proxy.example.com:1080\" # 可选：针对此 Key 的代理覆盖<br/>#       - api-key: \"sk-or-v1-...b781\" # 不使用特定代理<br/>#     models: # 提供商支持的模型列表。<br/>#       - name: \"moonshotai/kimi-k2:free\" # 实际模型名称。<br/>#         alias: \"kimi-k2\" # API 中使用的别名。<br/># Vertex API 密钥配置 (Vertex 兼容端点，使用 API key + base URL)<br/># vertex-api-key:<br/>#   - api-key: \"vk-123...\"                        # x-goog-api-key 头部使用的 Key<br/>#     prefix: \"test\"                              # 可选：前缀匹配<br/>#     base-url: \"https://example.com/api\"         # 例如 https://zenmux.ai/api<br/>#     proxy-url: \"socks5://proxy.example.com:1080\" # 可选：代理覆盖<br/>#     headers:<br/>#       X-Custom-Header: \"custom-value\"<br/>#     models:                                     # 可选：映射别名到上游模型名<br/>#       - name: \"gemini-2.5-flash\"                # 上游模型名<br/>#         alias: \"vertex-flash\"                   # 客户端可见别名<br/>#       - name: \"gemini-2.5-pro\"<br/>#         alias: \"vertex-pro\"<br/># Amp 集成配置 (AmpCode)<br/># ampcode:<br/>#   # 配置 Amp CLI OAuth 和管理功能的上游 URL<br/>#   upstream-url: \"https://ampcode.com\"<br/>#   # 可选：覆盖 Amp 上游 API Key (否则使用环境变量或文件)<br/>#   upstream-api-key: \"\"<br/>#   # 每个客户端的上游 API Key 映射<br/>#   # 将客户端 API Key (来自顶部的 api-keys) 映射到不同的 Amp 上游 API Key。<br/>#   # 当不同的客户端需要使用不同的 Amp 账号/配额时很有用。<br/>#   # 如果客户端 Key 未被映射，则回退使用 upstream-api-key (默认行为)。<br/>#   upstream-api-keys:<br/>#     - upstream-api-key: \"amp_key_for_team_a\"    # 这些客户端使用的上游 Key<br/>#       api-keys:                                 # 使用此上游 Key 的客户端 Key 列表<br/>#         - \"sk-ftiRC5M0nDSsM6LMDelpyHWL5x9ILsy3c1Nwlq1xJdd64\"<br/>#         - \"sk-LjCI3oAd7DKeXin6FvmiDuzZ9pL5MTLGcbIapwgBUQhsl\"<br/>#     - upstream-api-key: \"amp_key_for_team_b\"<br/>#       api-keys:<br/>#         - \"your-api-key-3\"<br/>#   # 限制 Amp 管理路由 (/api/auth, /api/user 等) 仅限 localhost 访问 (默认: false)<br/>#   restrict-management-to-localhost: false<br/>#   # 强制在检查本地 API Key 之前运行模型映射 (默认: false)<br/>#   force-model-mappings: false<br/>#   # Amp 模型映射<br/>#   # 将不可用的 Amp 模型路由到本地代理中可用的替代模型。<br/>#   # 当 Amp CLI 请求你没有权限访问的模型 (如 Claude Opus 4.5)，<br/>#   # 但你有类似的可用模型 (如 Claude Sonnet 4) 时很有用。<br/>#   model-mappings:<br/>#     - from: \"claude-opus-4-5-20251101\"          # Amp CLI 请求的模型<br/>#       to: \"gemini-claude-opus-4-5-thinking\"     # 路由到此可用模型代替<br/>#     - from: \"claude-sonnet-4-5-20250929\"<br/>#       to: \"gemini-claude-sonnet-4-5-thinking\"<br/>#     - from: \"claude-haiku-4-5-20251001\"<br/>#       to: \"gemini-2.5-flash\"<br/># 全局 OAuth 模型名称映射 (按通道/渠道)<br/># 这些映射会重命名模型 ID，同时影响模型列表和请求路由。<br/># 支持的通道: gemini-cli, vertex, aistudio, antigravity, claude, codex, qwen, iflow.<br/># 注意: 映射不适用于 gemini-api-key, codex-api-key, claude-api-key, openai-compatibility, vertex-api-key 或 ampcode 配置。<br/># oauth-model-mappings:<br/>#   gemini-cli:<br/>#     - name: \"gemini-2.5-pro\"          # 该通道下的原始模型名<br/>#       alias: \"g2.5p\"                  # 客户端可见别名<br/>#   vertex:<br/>#     - name: \"gemini-2.5-pro\"<br/>#       alias: \"g2.5p\"<br/>#   aistudio:<br/>#     - name: \"gemini-2.5-pro\"<br/>#       alias: \"g2.5p\"<br/>#   antigravity:<br/>#     - name: \"gemini-3-pro-preview\"<br/>#       alias: \"g3p\"<br/>#   claude:<br/>#     - name: \"claude-sonnet-4-5-20250929\"<br/>#       alias: \"cs4.5\"<br/>#   codex:<br/>#     - name: \"gpt-5\"<br/>#       alias: \"g5\"<br/>#   qwen:<br/>#     - name: \"qwen3-coder-plus\"<br/>#       alias: \"qwen-plus\"<br/>#   iflow:<br/>#     - name: \"glm-4.7\"<br/>#       alias: \"glm-god\"<br/># OAuth 提供商排除的模型<br/># oauth-excluded-models:<br/>#   gemini-cli:<br/>#     - \"gemini-2.5-pro\"     # 排除特定模型 (精确匹配)<br/>#     - \"gemini-2.5-*\"       # 通配符前缀<br/>#     - \"*-preview\"          # 通配符后缀<br/>#     - \"*flash*\"            # 通配符子串<br/>#   vertex:<br/>#     - \"gemini-3-pro-preview\"<br/>#   aistudio:<br/>#     - \"gemini-3-pro-preview\"<br/>#   antigravity:<br/>#     - \"gemini-3-pro-preview\"<br/>#   claude:<br/>#     - \"claude-3-5-haiku-20241022\"<br/>#   codex:<br/>#     - \"gpt-5-codex-mini\"<br/>#   qwen:<br/>#     - \"vision-model\"<br/>#   iflow:<br/>#     - \"tstars2.0\"<br/># 可选的 Payload (请求体) 配置<br/># payload:<br/>#   default: # 默认规则：仅当 Payload 中缺少参数时才设置参数。<br/>#     - models:<br/>#         - name: \"gemini-2.5-pro\" # 支持通配符 (例如 \"gemini-*\")<br/>#           protocol: \"gemini\" # 限制规则仅适用于特定协议，选项: openai, gemini, claude, codex<br/>#       params: # JSON 路径 (gjson/sjson 语法) -&gt; 值<br/>#         \"generationConfig.thinkingConfig.thinkingBudget\": 32768<br/>#   override: # 覆盖规则：总是设置参数，覆盖任何现有值。<br/>#     - models:<br/>#         - name: \"gpt-*\" # 支持通配符 (例如 \"gpt-*\")<br/>#           protocol: \"codex\" # 限制规则仅适用于特定协议，选项: openai, gemini, claude, codex<br/>#       params: # JSON 路径 (gjson/sjson 语法) -&gt; 值<br/>#         \"reasoning.effort\": \"high\"</pre>\n</div>\n</div>\n<p>4. 启动服务</p>\n<p>在目录下打开终端（PowerShell / CMD）：</p>\n<div class=\"code-block-decoration header-formatted gds-title-s ng-tns-c2283161342-143 ng-star-inserted\">\n<div class=\"formatted-code-block-internal-container ng-tns-c2283161342-143\">\n<div class=\"animated-opacity ng-tns-c2283161342-143\">\n<pre class=\"ng-tns-c2283161342-143\"><code class=\"code-container formatted ng-tns-c2283161342-143\">docker-compose up -d</code></pre>\n5.<strong>进行 OAuth 登录认证 (最关键的一步)</strong>\n<p>容器虽然在运行，但它还没有登录你的 OpenAI/Gemini 账户，无法工作。我们需要进入容器执行登录命令或者进入网页管理端http://127.0.0.1/management.html。</p>\n<ol>\n<li><strong>找到可执行文件</strong></li>\n</ol>\n<p>由于不同版本的镜像可能把文件放在不同位置，我们先进入容器内部查找。</p>\n<pre>docker exec -it cli-proxy-api-compose sh</pre>\n</div>\n</div>\n</div>\n<div class=\"formatted-code-block-internal-container ng-tns-c2283161342-143\">\n<div class=\"animated-opacity ng-tns-c2283161342-143\">\n<div class=\"code-block-decoration header-formatted gds-title-s ng-tns-c2283161342-143 ng-star-inserted\">\n<div class=\"formatted-code-block-internal-container ng-tns-c2283161342-143\">\n<div class=\"animated-opacity ng-tns-c2283161342-143\">\n<p>    2.<strong>执行登录命令</strong></p>\n<ul>\n<li>执行后，终端会打印出一个很长的 URL 链接。</li>\n</ul>\n</div>\n</div>\n</div>\n<div class=\"formatted-code-block-internal-container ng-tns-c2283161342-143\">\n<div class=\"animated-opacity ng-tns-c2283161342-143\">\n<pre class=\"ng-tns-c2283161342-143\">./CLIProxyAPI --antigravity-login --no-browser</pre>\n</div>\n</div>\n<p><strong>    在浏览器中完成授权</strong></p>\n<ul>\n<li>\n<ul>\n<li>复制这个完整的 URL。</li>\n<li>把它粘贴到你<strong>个人电脑</strong>的浏览器中打开。</li>\n<li>登录你的gemini 账户并点击授权。</li>\n<li>授权成功后，网页会跳转新的url，复制url链接在终端粘贴即可</li>\n</ul>\n</li>\n</ul>\n</div>\n</div>','2026-01-01 22:29:01.873457','2026-01-09 14:31:52.387585',1,'00f51733bcc34bbda62df2d7de171731',2,2,26,'[{\"id\": \"cliproxyapi-quick-start\", \"text\": \"🚀 CLIProxyAPI 搭建笔记 (Quick Start)\", \"level\": 1}, {\"id\": \"\", \"text\": \"项目简介\", \"level\": 2}, {\"id\": \"-2\", \"text\": \"🛠️ 环境准备\", \"level\": 2}, {\"id\": \"-3\", \"text\": \"📦 部署方案 ：\", \"level\": 2}, {\"id\": \"2-docker-composeyml\", \"text\": \"2. 编写 docker-compose.yml\", \"level\": 3}]',NULL,0,0,NULL,0),(14,'Google Cloud','<p>---</p>\n<p># GCP (Google Cloud) 开启 SSH 密钥登录与 Root 权限配置完全指南</p>\n<p>在 Google Cloud Platform (GCP) 上创建虚拟机（VPS）后，默认推荐使用浏览器自带的 SSH 连接。但在日常使用中，使用本地终端（如 PowerShell, CMD, Mac Terminal）配合 SSH 密钥登录更加方便、稳定且安全。</p>\n<p>本教程将手把手教你生成 SSH 密钥，并配置 GCP 允许 Root 用户直接登录。</p>\n<p>---</p>\n<p>## 第一步：在本地生成 SSH 密钥对</p>\n<p>我们需要在你的电脑上生成一把“钥匙”（私钥）和一个“锁芯”（公钥）。</p>\n<p>1.  **打开终端**：<br/>    *   Windows 用户打开 **PowerShell** 或 **CMD**。<br/>    *   Mac/Linux 用户打开 **Terminal**。</p>\n<p>2.  **输入生成命令**：<br/>    我们使用目前最安全且高效的 `ed25519` 算法。<br/>    ```powershell<br/>    ssh-keygen -t ed25519 -C \"root\"<br/>    ```<br/>    *解释：`-C \"root\"` 是注释，表示这个密钥是给 root 用的（方便识别，也可以填你的邮箱）。*</p>\n<p>3.  **按提示操作**：<br/>    *   系统会问你保存路径，**直接按回车**（默认保存在 `~/.ssh/id_ed25519`）。<br/>    *   系统会问你是否设置密码（Passphrase），为了方便脚本使用，**通常直接按回车留空**。</p>\n<p>4.  **查看公钥内容**：<br/>    生成后，我们需要复制公钥（锁芯）的内容。<br/>    *   **Windows**: `cat ~\\.ssh\\id_ed25519.pub`<br/>    *   **Mac/Linux**: `cat ~/.ssh/id_ed25519.pub`</p>\n<p>    **复制输出的那一行以 `ssh-ed25519` 开头的完整字符串。**</p>\n<p>---</p>\n<h3 id=\"gcp\">第二步：添加密钥到 GCP</h3>\n<p>你可以选择将密钥添加给<strong>某一台特定的服务器</strong>，或者<strong>项目下的所有服务器</strong>。</p>\n<h4 id=\"a\">方法 A：针对单个实例添加（推荐）</h4>\n<p>如果你只想访问特定的 VM，用这个方法。</p>\n<ol>\n<li>登录 <a href=\"https://console.cloud.google.com/\" rel=\"noopener noreferrer\" target=\"_blank\">GCP 控制台</a>。</li>\n<li>导航到 <strong>Compute Engine</strong> -&gt; <strong>VM 实例 (VM instances)</strong>。</li>\n<li>点击你想要添加密钥的实例<strong>名称</strong>。</li>\n<li>点击顶部的 <strong>编辑 (Edit)</strong> 按钮。</li>\n<li>向下滚动，找到 <strong>SSH 密钥 (SSH Keys)</strong> 部分（注意：不要混淆成“自定义元数据”）。\n<ul>\n<li><em>注：你可能需要先点击“安全和访问权限”或类似折叠菜单展开它。</em></li>\n</ul>\n</li>\n<li>点击 <strong>添加项 (Add item)</strong>。</li>\n<li>在文本框中粘贴你 <strong>第一步</strong> 中准备好的、带用户名前缀的公钥字符串。\n<ul>\n<li>格式例如公钥字符串:用户名</li>\n</ul>\n</li>\n<li>滚动到页面最底部，点击 <strong>保存 (Save)</strong>。</li>\n</ol>\n<h4><img src=\"../protected_uploads/user_2/mceclip0.png\"/></h4>\n<h4 id=\"b\">方法 B：项目级添加（所有实例通用）</h4>\n<p>如果你希望这个密钥能登录该项目下<strong>所有</strong>未屏蔽项目元数据的 Linux 实例。</p>\n<ol>\n<li>登录 <a href=\"https://console.cloud.google.com/\" rel=\"noopener noreferrer\" target=\"_blank\">GCP 控制台</a>。</li>\n<li>导航到 <strong>Compute Engine</strong> -&gt; <strong>设置 (Settings)</strong> -&gt; <strong>元数据 (Metadata)</strong>。</li>\n<li>点击顶部的 <strong>SSH 密钥 (SSH Keys)</strong> 选项卡。</li>\n<li>点击 <strong>编辑 (Edit)</strong>。</li>\n<li>点击 <strong>添加项 (Add item)</strong>，粘贴你的公钥内容（同样需要 <code>ssh-rsa...:用户名</code> 格式）。例如：ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAINitNimyfd2ZVSm/p9q3KJtH0LfKJCbsC/bNe2Tzy1md root</li>\n<li>点击 <strong>保存 (Save)</strong>。\n<ul>\n<li><em>GCP 会自动将此密钥分发到项目中的所有 VM。</em></li>\n</ul>\n</li>\n</ol>\n<p><img src=\"../protected_uploads/user_2/mceclip0_epmFATL.png\"/><br/>    7.  滚动到底部，点击 **“保存”**。</p>\n<p> </p>\n<p>---</p>\n<p>## 第三步：在本地测试连接</p>\n<p>配置完成！现在回到你本地电脑的 PowerShell 或终端进行连接。</p>\n<p>**连接命令格式**：<br/>`ssh -i \"私钥路径\" 用户名@服务器IP`</p>\n<p>**示例**：<br/>```powershell<br/>ssh -i \"C:\\Users\\YourName\\.ssh\\id_ed25519\" root@35.188.xx.xx<br/>```</p>\n<p>如果一切顺利，你应该会直接进入系统，看到 `root@instance-name:~#` 的提示符。</p>\n<p>---</p>\n<p><img src=\"../protected_uploads/user_2/mceclip1_d0QqYAI.png\"/></p>\n<p>## 常见问题排查</p>\n<p>*   **Q: 提示 `Permission denied (publickey)`？**<br/>    *   A: 检查第二步中 GCP 后台填写的用户名是否为 `root`。检查本地命令是否加了 `-i 密钥路径`。<br/>*   **Q: 提示 `WARNING: REMOTE HOST IDENTIFICATION HAS CHANGED`？**<br/>    *   A: 你重装过系统。去本地 `C:\\Users\\你的用户名\\.ssh\\` 文件夹下，删除 `known_hosts` 文件，然后重试。</p>','2026-01-02 02:56:47.602351','2026-01-18 13:11:09.367417',1,'e458a0cde6e14b3d821a64820f72c404',2,2,25,'[{\"id\": \"gcp\", \"text\": \"第二步：添加密钥到 GCP\", \"level\": 3}, {\"id\": \"a\", \"text\": \"方法 A：针对单个实例添加（推荐）\", \"level\": 4}, {\"id\": \"b\", \"text\": \"方法 B：项目级添加（所有实例通用）\", \"level\": 4}]',NULL,0,0,NULL,0),(15,'无标题笔记','','2026-01-05 16:27:18.762106','2026-01-05 16:27:18.762106',0,'4993eaa5e2664422a7877e36490aac44',2,NULL,0,'[]',NULL,1,0,'2026-01-05 18:14:58.882094',0),(16,'无标题笔记','','2026-01-05 18:14:27.551397','2026-01-05 18:14:27.551397',0,'e7109bf561134baf802860e7af8f1f27',2,NULL,0,'[]',NULL,1,0,'2026-01-05 18:15:02.203490',0),(18,'无标题笔记','','2026-01-05 18:14:38.121773','2026-01-05 18:14:38.121773',0,'3e944581d2fe49f98034c07cc15f211b',2,NULL,0,'[]',NULL,1,0,'2026-01-05 18:15:08.488317',0),(19,'无标题笔记','','2026-01-05 18:16:05.666573','2026-01-05 18:16:05.666573',0,'7cb4188259a946fb89581ca6fd7d5b57',2,NULL,0,'[]',NULL,1,0,'2026-01-05 18:16:14.263867',0),(21,'无标题笔记','','2026-01-06 17:51:50.868612','2026-01-06 17:51:50.868612',0,'107da1ed9e404f1cb2062eb6e2a32688',2,NULL,0,'[]',NULL,1,0,'2026-01-06 17:52:37.208394',0),(23,'无标题笔记','','2026-01-06 17:52:02.042361','2026-01-06 17:52:02.042361',0,'fc89a7f4f5c34ff6b2634f7321d21493',2,NULL,0,'[]',NULL,1,0,'2026-01-06 17:52:32.812598',0),(28,'无标题笔记','','2026-01-06 18:15:50.866949','2026-01-06 18:15:50.866949',0,'980546c1189e4b1886a251e96c93882b',2,NULL,0,'[]',NULL,1,0,'2026-01-06 18:27:06.201169',0),(31,'无标题笔记','','2026-01-06 18:27:40.694570','2026-01-06 18:27:40.694570',0,'531f9c8f531043a1acbb7112d18719ea',2,NULL,0,'[]',NULL,1,0,'2026-01-06 18:31:31.345175',0),(32,'无标题笔记','','2026-01-06 18:31:26.638029','2026-01-06 18:31:26.638029',0,'98572508354b45799f85766dffadc704',2,NULL,0,'[]',NULL,1,0,'2026-01-06 18:31:59.371092',0),(34,'无标题笔记','','2026-01-06 18:32:45.114996','2026-01-06 18:32:45.114996',0,'f9c08ba8ba5b46f39c3b45ca198ad3f9',2,NULL,0,'[]',NULL,1,0,'2026-01-06 18:34:17.907188',0),(39,'无标题笔记','','2026-01-07 18:04:55.508800','2026-01-07 18:04:55.508800',0,'a3123dbab99e4739ae54477ee224e6fe',2,NULL,0,'[]',NULL,1,0,'2026-01-08 17:53:57.064473',0),(44,'无标题笔记','<p>awdad</p>','2026-01-08 18:30:26.098453','2026-01-18 12:18:19.697723',0,'bf4a1801ddb04240bf621ecfe494c1c9',2,2,0,'[]',3,1,0,'2026-01-18 12:18:19.688670',0),(49,'无标题笔记','<p>awdda</p>','2026-01-18 13:11:24.964168','2026-01-18 13:11:28.438967',0,'cc65c9fa5423473dbce884f97572caab',2,2,0,'[]',4,1,1,'2026-01-23 17:37:41.701586',0),(50,'123','','2026-01-18 13:29:17.198935','2026-01-21 11:25:43.647496',0,'0ed339e9fe73498b9f722b01c207fc84',2,2,0,'[]',4,1,0,'2026-01-23 17:37:35.979872',0),(51,'无标题笔记','','2026-01-23 17:36:52.506453','2026-01-23 17:36:57.345409',0,'8ad58e0703be4af29edb04ae147ec88b',2,2,0,'[]',NULL,1,0,'2026-01-25 10:57:56.274261',0),(52,'Team_Project','<p>## 📋 項目概述</p>\n<p>**Team_Project** 是一個基於 Django + Vue 的全棧 Web 應用，提供筆記管理、保密柜加密存儲、用戶認證等核心功能。</p>\n<p>---</p>\n<p>## ✨ 主要功能模塊</p>\n<p>### 1️⃣ **用戶認證與安全**<br>- ✅ 註冊/登錄（支持驗證碼和 Turnstile 驗證）<br>- ✅ 兩因素認證（2FA）- TOTP 和郵件驗證<br>- ✅ 密碼重置（帶郵件驗證和令牌機制）<br>- ✅ 登錄設備識別和可疑登錄通知<br>- ✅ 登錄通知系統（防止未授權訪問）</p>\n<p>### 2️⃣ **筆記管理系統**<br>- ✅ CRUD 操作（創建、讀取、更新、刪除）<br>- ✅ 文件夾組織和層級結構<br>- ✅ 標籤系統自動生成<br>- ✅ 收藏功能<br>- ✅ 回收站機制（軟刪除）<br>- ✅ 完整搜索功能</p>\n<p>### 3️⃣ **保密柜（Vault）系統** ⭐ 安全特性<br>- ✅ 密碼保護的私密筆記區域<br>- ✅ 郵箱驗證碼驗證<br>- ✅ 自動鎖定機制（30分鐘無活動自動鎖定）<br>- ✅ 帳戶鎖定機制（驗證失敗次數過多）<br>&nbsp; - 第3次失敗：鎖定1分鐘<br>&nbsp; - 第5次失敗：鎖定24小時<br>- ✅ 中間件級別的訪問控制</p>\n<p>### 4️⃣ **社交與互動功能**<br>- ✅ 個人資料頁面（頭像、簽名、統計）<br>- ✅ 點贊系統（用戶資料、筆記）<br>- ✅ 公開筆記展示<br>- ✅ 點贊通知</p>\n<p>### 5️⃣ **文件與媒體處理**<br>- ✅ 圖片上傳和處理<br>- ✅ CKEditor 5 編輯器集成<br>- ✅ 文件哈希去重<br>- ✅ 受保護的文件訪問</p>\n<p>### 6️⃣ **通知系統**<br>- ✅ 郵件通知（可配置）<br>- ✅ 登錄通知<br>- ✅ 密碼修改通知<br>- ✅ 筆記活動通知<br>- ✅ 點贊通知</p>\n<p>---</p>\n<p>## 🛡️ 安全機制</p>\n<p>### 核心安全特性<br>```<br>✅ CSRF 保護<br>✅ XSS 防護（nh3 HTML 清理）<br>✅ 內容安全策略（CSP）響應頭<br>✅ SQL 注入防護（Django ORM）<br>✅ 驗證碼（圖片+Turnstile 混合）<br>✅ 速率限制（多層次）<br>✅ 郵箱和用戶名檢查（防暴露用戶隱私）<br>```</p>\n<p>### Vault Lock 中間件（v2.0）<br>- **當保密柜被鎖定時**：<br>&nbsp; - 🚫 阻止所有敏感數據讀取<br>&nbsp; - 🚫 阻止所有寫入操作<br>&nbsp; - ✅ 允許白名單操作（登出、密碼重置）<br>&nbsp; - ✅ 防止「殭屍會話」攻擊</p>\n<p>---</p>\n<p>## 🏗️ 技術棧</p>\n<p>### 後端<br>```<br>Django 5.2 + MySQL<br>Django REST Framework（隱含）<br>Jieba 中文分詞<br>BeautifulSoup HTML 解析<br>Pillow 圖像處理<br>PyOTP 2FA<br>nh3 HTML 清理<br>```</p>\n<p>### 前端<br>```<br>Vue 3（組件框架）<br>Vite（構建工具）<br>Element Plus（UI 組件）<br>CKEditor 5（富文本編輯）<br>TinyMCE（備用編輯器）<br>```</p>\n<p>---</p>\n<p>## 📊 數據庫模型</p>\n<p>| 模型 | 說明 |<br>|------|------|<br>| **User** | Django 內置用戶模型 |<br>| **Profile** | 用戶資料（頭像、簽名、2FA、通知偏好） |<br>| **Note** | 筆記（內容、權限、回收站標記） |<br>| **Folder** | 文件夾（層級組織） |<br>| **Tag** | 標籤 |<br>| **Asset** | 文件資源 |<br>| **LoginDevice** | 登錄設備指紋 |<br>| **LoginNotification** | 登錄通知記錄 |<br>| **PasswordResetToken** | 密碼重置令牌 |<br>| **PasswordResetAttempt** | 密碼重置速率限制 |</p>\n<p>---</p>\n<p>## 🎯 API 端點（核心）</p>\n<p>### 認證 API<br>```<br>POST /api/login/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;# 登錄<br>POST /api/2fa/verify/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 2FA 驗證<br>GET &nbsp;/api/captcha/init/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 初始化驗證碼<br>```</p>\n<p>### 筆記 API<br>```<br>GET &nbsp;/api/notes/all/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;# 所有筆記<br>POST /api/notes/create/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 創建筆記<br>GET &nbsp;/api/notes/&lt;id&gt;/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 筆記詳情<br>PUT &nbsp;/api/notes/&lt;id&gt;/update/ &nbsp; &nbsp; &nbsp; &nbsp;# 更新筆記<br>DELETE /api/notes/&lt;id&gt;/delete/ &nbsp; &nbsp; &nbsp;# 刪除筆記<br>GET &nbsp;/api/notes/search/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 搜索筆記<br>```</p>\n<p>### 保密柜 API<br>```<br>GET &nbsp;/api/vault/status/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 檢查狀態<br>POST /api/vault/verify/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 驗證密碼<br>POST /api/vault/lock/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 主動鎖定<br>GET &nbsp;/api/vault/notes/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;# 保密筆記列表<br>POST /api/vault/send-email-code/ &nbsp; &nbsp;# 發送驗證碼<br>```</p>\n<p>### 文件夾 API<br>```<br>GET &nbsp;/api/folders/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;# 文件夾列表<br>GET &nbsp;/api/folders/&lt;id&gt;/notes/ &nbsp; &nbsp; &nbsp; # 文件夾內筆記<br>POST /api/notes/&lt;id&gt;/move/ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;# 移動筆記<br>```</p>\n<p>---</p>\n<p>## 💡 建議與改進方案</p>\n<p>### 🔴 **HIGH 優先級問題**</p>\n<p>#### 1. **代碼組織與可維護性**<br>```<br>現狀：views.py 過大（3000+ 行），難以維護<br>建議：<br>&nbsp; - 按功能拆分模塊：<br>&nbsp; &nbsp; ✓ views/auth.py (認證相關)<br>&nbsp; &nbsp; ✓ views/notes.py (筆記相關)<br>&nbsp; &nbsp; ✓ views/vault.py (保密柜相關)<br>&nbsp; &nbsp; ✓ views/profile.py (用戶資料相關)<br>&nbsp; - 使用 ViewSets 和 Routers（如有 DRF）<br>```</p>\n<p>#### 2. **缺少測試覆蓋**<br>```<br>現狀：有測試文件但覆蓋不完整<br>建議：<br>&nbsp; - 添加單元測試（unittest/pytest）<br>&nbsp; - API 集成測試（Django TestCase）<br>&nbsp; - 安全測試（CSRF、SQL 注入、XSS）<br>&nbsp; - Vault 鎖定機制的邊界測試<br>```</p>\n<p>#### 3. **文件上傳安全**<br>```<br>現狀：已有哈希驗證，但建議補充：<br>&nbsp; - ✓ 文件類型白名單驗證<br>&nbsp; ✓ 文件大小限制（防 DoS）<br>&nbsp; ✓ 反病毒掃描集成（可選）<br>&nbsp; ✓ CDN 緩存配置<br>```</p>\n<p>### 🟡 **MEDIUM 優先級問題**</p>\n<p>#### 4. **日誌記錄**<br>```<br>現狀：有基本的 logger.error 調用<br>建議：<br>&nbsp; - 結構化日誌（JSON 格式）<br>&nbsp; - 日誌聚合（ELK Stack 或類似）<br>&nbsp; - 安全事件專用日誌（認證失敗、Vault 鎖定等）<br>&nbsp; - 審計日誌（谁修改了什麼，何時）<br>```</p>\n<p>#### 5. **性能優化**<br>```<br>現狀：已有緩存機制<br>建議：<br>&nbsp; - 使用 Redis 替代內存緩存<br>&nbsp; - 數據庫索引優化（已有部分）<br>&nbsp; - 分頁 API（防止大數據集）<br>&nbsp; - 懶加載和虛擬滾動（前端）<br>&nbsp; - 批量操作端點<br>```</p>\n<p>#### 6. **API 版本控制**<br>```<br>現狀：無版本控制<br>建議：<br>&nbsp; - 添加 API 版本前綴：/api/v1/<br>&nbsp; - 保持向後兼容性<br>&nbsp; - 版本棄用計劃<br>```</p>\n<p>### 🟢 **LOW 優先級問題**</p>\n<p>#### 7. **前端工程化**<br>```<br>現狀：Vite + Vue 3，但可優化<br>建議：<br>&nbsp; - 類型檢查（TypeScript）<br>&nbsp; - 代碼質量（ESLint + Prettier）<br>&nbsp; - 自動化測試（Vitest、Playwright）<br>&nbsp; - 性能監控（Web Vitals）<br>```</p>\n<p>#### 8. **國際化（i18n）**<br>```<br>現狀：中文優先，缺少多語言支持<br>建議：<br>&nbsp; - 使用 django-rosetta 或 DjangoJS i18n<br>&nbsp; - 前端使用 vue-i18n<br>&nbsp; - 翻譯文件版本控制<br>```</p>\n<p>#### 9. **文檔完善**<br>```<br>現狀：有部分 .md 文件，但不完整<br>建議：<br>&nbsp; - API 文檔（Swagger/OpenAPI）<br>&nbsp; - 安裝和部署指南<br>&nbsp; - 開發者指南<br>&nbsp; - 貢獻指南<br>&nbsp; - 疑難解答文檔<br>```</p>\n<p>#### 10. **監控與告警**<br>```<br>建議：<br>&nbsp; - 應用性能監控（APM）<br>&nbsp; - 錯誤追蹤（Sentry）<br>&nbsp; - 健康檢查端點<br>&nbsp; - 自動告警配置<br>```</p>\n<p>---</p>\n<p>## 🔒 安全建議補充</p>\n<p>1. **環境變量管理**<br>&nbsp; &nbsp;- ✓ 已使用 `.env`，確保 `.env` 在 `.gitignore` 中<br>&nbsp; &nbsp;- ✓ 定期輪換敏感密鑰</p>\n<p>2. **依賴管理**<br>&nbsp; &nbsp;```bash<br>&nbsp; &nbsp;# 定期檢查漏洞<br>&nbsp; &nbsp;pip install safety<br>&nbsp; &nbsp;safety check<br>&nbsp; &nbsp;```</p>\n<p>3. **密碼策略**<br>&nbsp; &nbsp;- ✓ 已有最小長度 9<br>&nbsp; &nbsp;- 建議：添加密碼過期政策</p>\n<p>4. **Vault 驗證邏輯**<br>&nbsp; &nbsp;- ✓ 已有指數退避機制<br>&nbsp; &nbsp;- 建議：添加行為分析（異常登錄模式檢測）</p>\n<p>---</p>\n<p>## 📈 部署建議</p>\n<p>```yaml<br>開發環境:<br>&nbsp; - DEBUG = True<br>&nbsp; - SQLite（快速測試）</p>\n<p>測試環境:<br>&nbsp; - DEBUG = False<br>&nbsp; - MySQL（與生產一致）<br>&nbsp; - 郵件後端 = console</p>\n<p>生產環境:<br>&nbsp; - DEBUG = False<br>&nbsp; - MySQL（主從複製）<br>&nbsp; - Redis（緩存 + 會話存儲）<br>&nbsp; - HTTPS（強制）<br>&nbsp; - 反向代理（Nginx）<br>&nbsp; - 應用伺服器（Gunicorn + Supervisor）<br>```</p>\n<p>---</p>\n<p>## 📝 總結評分</p>\n<p>| 維度 | 評分 | 備註 |<br>|------|------|------|<br>| **功能完整性** | ⭐⭐⭐⭐⭐ | 功能齊全、核心特性完整 |<br>| **代碼品質** | ⭐⭐⭐☆☆ | 邏輯正確，但組織需改進 |<br>| **安全性** | ⭐⭐⭐⭐☆ | 安全機制齊全，建議加強日誌 |<br>| **測試覆蓋** | ⭐⭐☆☆☆ | 測試不足，建議補充 |<br>| **文檔** | ⭐⭐⭐☆☆ | 部分文檔完整，需統一 |<br>| **可維護性** | ⭐⭐⭐☆☆ | 需要重構大型模塊 |</p>\n<p>---</p>\n<p>這是一個 **生產級質量的應用**，具有優秀的安全設計和完整的功能。主要改進方向是 **代碼組織**、**測試覆蓋** 和 **運維監控**。</p>','2026-01-25 10:12:25.010563','2026-01-25 10:12:43.548126',0,'d7e4f633145c4285a4aed093bbd13771',2,2,0,'[]',NULL,0,0,NULL,0),(53,'123','<p>123</p>','2026-01-25 10:23:54.372212','2026-01-25 11:57:35.026070',0,'c9c38c29b97746b8923b6b739f85097f',2,2,0,'[]',NULL,0,0,NULL,0),(54,'无标题笔记','','2026-01-25 10:48:36.618934','2026-01-25 10:48:45.340075',0,'476d8b6b67c6426f901bdf1341886742',2,2,0,'[]',NULL,1,0,'2026-01-25 10:57:59.094809',0),(55,'无标题笔记','','2026-01-25 11:25:22.161275','2026-01-25 11:25:24.916757',0,'c40044d1811246779afc2c93c554262f',2,2,0,'[]',NULL,1,0,'2026-01-25 11:25:31.221522',1);
